'use strict';
// Opt-in real Internet test. Transfers generated bytes only, never user media.
const DHT = require('hyperdht');
const fs = require('node:fs/promises');
const path = require('node:path');
const os = require('node:os');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const { once } = require('node:events');
const BOOTSTRAP = ['88.99.3.86:49737', '142.93.90.113:49737', '138.68.147.8:49737'];
const digest = value => crypto.createHash('sha256').update(value).digest('hex');
const output = path.resolve(process.env.FREECUT_NETWORK_QA_OUTPUT || '.cache/internet-link');
const mode = process.argv[2];
function deadline(promise, ms, label) {
  let timer;
  return Promise.race([promise, new Promise((_, reject) => { timer = setTimeout(() => reject(Error(label)), ms); })])
    .finally(() => clearTimeout(timer));
}
async function createNode() {
  const candidates = [...new Set(Object.values(os.networkInterfaces()).flat()
    .filter(item => item?.family === 'IPv4' && !item.internal && !/^198\.(18|19)\./.test(item.address))
    .map(item => item.address))];
  candidates.sort((a, b) => Number(!a.startsWith('192.168.')) - Number(!b.startsWith('192.168.')));
  candidates.push('0.0.0.0');
  for (const host of candidates) {
    const node = new DHT({ host, bootstrap: BOOTSTRAP, ephemeral: true, port: 26000 + crypto.randomInt(20000) });
    node.on('error', () => {});
    try {
      await deadline(Promise.any(BOOTSTRAP.map(address => {
        const [ip, port] = address.split(':');
        return node.ping({ host: ip, port: Number(port) });
      })), 8000, 'Public discovery did not respond');
      return node;
    } catch { await node.destroy({ force: true }); }
  }
  throw Error('No network interface reached the public discovery nodes');
}
function collect(socket, maximum) {
  return new Promise((resolve, reject) => {
    const chunks = []; let bytes = 0;
    socket.on('data', chunk => {
      bytes += chunk.length;
      if (bytes > maximum) { socket.destroy(); reject(Error('Test response exceeds limit')); }
      else chunks.push(chunk);
    });
    socket.once('end', () => resolve(Buffer.concat(chunks)));
    socket.once('error', reject);
  });
}
function parse(buffer) {
  const line = buffer.indexOf(10);
  assert(line > 0 && line < 1024, 'Invalid test envelope');
  return { header: JSON.parse(buffer.subarray(0, line).toString()), bytes: buffer.subarray(line + 1) };
}
async function main() {
  assert(['host', 'join'].includes(mode), 'Use host or join');
  await fs.mkdir(output, { recursive: true });
  const node = await createNode();
  const sockets = new Set();
  const report = { mode, platform: process.platform, arch: process.arch, started: new Date().toISOString(), passed: false };
  try {
    if (mode === 'host') {
      const keyPair = DHT.keyPair();
      const challenge = crypto.randomBytes(32).toString('hex');
      const download = crypto.randomBytes(4 * 1024 ** 2);
      let finish, fail;
      const completed = new Promise((resolve, reject) => { finish = resolve; fail = reject; });
      const server = node.createServer({ firewall: () => sockets.size >= 2 }, socket => {
        sockets.add(socket); socket.on('close', () => sockets.delete(socket));
        const received = []; let length = 0, wanted;
        socket.on('error', fail);
        socket.on('data', chunk => {
          try {
            length += chunk.length;
            assert(length <= 3 * 1024 ** 2 + 1024, 'Test request exceeds limit');
            received.push(chunk);
            const buffer = Buffer.concat(received);
            const line = buffer.indexOf(10);
            if (line < 0) return;
            const { header, bytes } = parse(buffer);
            assert.equal(header.challenge, challenge);
            assert.equal(header.length, 3 * 1024 ** 2);
            wanted = header.length;
            if (bytes.length < wanted) return;
            assert.equal(bytes.length, wanted); assert.equal(digest(bytes), header.sha256);
            socket.removeAllListeners('data');
            const response = { ok: true, uploadSha: header.sha256, length: download.length, sha256: digest(download) };
            report.uploadBytes = bytes.length; report.downloadBytes = download.length;
            socket.end(Buffer.concat([Buffer.from(JSON.stringify(response) + '\n'), download]), finish);
          } catch (error) { socket.destroy(); fail(error); }
        });
      });
      await deadline(server.listen(keyPair), 60000, 'Internet announce timed out');
      // HyperDHT 6.34.0 records successful announce acknowledgements here.
      assert(server._announcer?.relays?.length > 0, 'No verified public announcement');
      await fs.writeFile(path.join(output, 'connection.json'), JSON.stringify({ publicKey: keyPair.publicKey.toString('hex'), challenge }));
      console.log('Internet test host ready; temporary connection information saved locally.');
      await deadline(completed, 15 * 60 * 1000, 'No successful cross-network peer within test window');
      report.passed = true;
    } else {
      const publicKey = process.env.FREECUT_NETWORK_QA_PEER;
      const challenge = process.env.FREECUT_NETWORK_QA_CHALLENGE;
      assert(/^[a-f0-9]{64}$/.test(publicKey || '')); assert(/^[a-f0-9]{64}$/.test(challenge || ''));
      const start = Date.now();
      const socket = node.connect(Buffer.from(publicKey, 'hex'), { localConnection: false });
      sockets.add(socket);
      const result = collect(socket, 4 * 1024 ** 2 + 1024);
      // Install a rejection handler before the awaited handshake can fail.
      result.catch(() => {});
      await deadline(once(socket, 'open'), 60000, 'Remote encrypted connection timed out');
      assert.equal(socket.remotePublicKey.toString('hex'), publicKey);
      report.connectMilliseconds = Date.now() - start;
      const upload = crypto.randomBytes(3 * 1024 ** 2);
      const header = { challenge, length: upload.length, sha256: digest(upload) };
      socket.write(Buffer.from(JSON.stringify(header) + '\n'));
      for (let offset = 0; offset < upload.length; offset += 65536) {
        await new Promise((resolve, reject) => socket.write(upload.subarray(offset, offset + 65536), error => error ? reject(error) : resolve()));
      }
      const response = parse(await deadline(result, 120000, 'Cross-network transfer timed out'));
      assert.equal(response.header.ok, true); assert.equal(response.header.uploadSha, digest(upload));
      assert.equal(response.bytes.length, 4 * 1024 ** 2); assert.equal(digest(response.bytes), response.header.sha256);
      report.uploadBytes = upload.length; report.downloadBytes = response.bytes.length;
      report.totalMilliseconds = Date.now() - start; report.remoteKeyVerified = true; report.passed = true;
    }
  } catch (error) { report.error = error.message; throw error; }
  finally {
    await fs.writeFile(path.join(output, `${mode}-report.json`), JSON.stringify(report, null, 2));
    for (const socket of sockets) socket.destroy();
    await node.destroy({ force: true });
  }
  console.log(JSON.stringify(report));
}
main().catch(error => { console.error(error.message); process.exitCode = 1; });
